DO $v4$ DECLARE name text; definition text; BEGIN
  FOREACH name IN ARRAY ARRAY['run_producers_execution_profile_id_check','run_producers_execution_profile_digest_check','run_producers_full03_exact_check'] LOOP
    SELECT pg_get_constraintdef(oid) INTO STRICT definition FROM pg_constraint WHERE conrelid='research.run_producers'::regclass AND conname=name;
    IF left(definition,7)<>'CHECK (' OR right(definition,1)<>')' THEN RAISE EXCEPTION 'unsupported exact recipe constraint'; END IF;
    EXECUTE format('ALTER TABLE research.run_producers DROP CONSTRAINT %I',name);
    EXECUTE format('ALTER TABLE research.run_producers ADD CONSTRAINT %I CHECK ((%s) OR (%s))',name,substring(definition from 8 for char_length(definition)-8),'execution_profile_id=''p10.delta-intrabar-bracket-fixed-1h.v4'' AND execution_profile_digest=''b6a17c962f64c462fd7db2859160f2ef37547903e0084d00694ecc8dea5e20f0'' AND execution_adapter_id=''full03.delta-rsi.v1'' AND adapter_contract_digest=''15cb147a294ac5ce76c27781481336b4b17fc35f1e8fc1f4a33405756e4b059c'' AND alpha_id=''delta-rsi-polynomial-alpha'' AND alpha_version_id=''av_delta_rsi_polynomial_alpha_1_0_9''');
  END LOOP;
END $v4$;
